    /** Performs the request; a non-2xx status decodes its declared error model into {@link SdkHttpError#data}. */
    public static <T> SdkResponse<T> request(
        SdkConfig.ClientConfig config,
        String method,
        String path,
        Map<String, Object> query,
        Object body,
        String contentType,
        TypeReference<T> returnType,
        String operationId,
        Map<String, String> extraHeaders,
        ResponseDecoder decoder,
        SdkConfig.RequestOptions options,
        Map<String, Class<? extends ErrorBody>> errors
    ) {
        RequestPlan plan = prepareRequest(
            config,
            method,
            path,
            query,
            body,
            contentType,
            operationId,
            extraHeaders,
            options,
            errors
        );
        for (int attempt = 1; attempt <= plan.retry.maxAttempts; attempt++) {
            SdkConfig.SdkRequest req = plan.request(attempt);
            SdkConfig.ClientConfig cfg = plan.config;
            SdkConfig.SdkNext terminal = (r) -> coreTransport(r, plan.timeout);
            SdkConfig.SdkNext dispatch = composeMiddleware(cfg.middleware, terminal);

            try {
                SdkConfig.SdkRawResponse resp = dispatch.handle(req);
                if (resp.statusCode >= 200 && resp.statusCode < 300) {
                    T data = decodeResponse(resp, returnType, decoder, operationId);
                    SdkResponse<T> envelope = new SdkResponse<>(data, resp.statusCode, resp.headers, resp.requestId, resp.latency, resp.attempt);
                    if (cfg.onResponse != null) cfg.onResponse.accept(envelope);
                    return envelope;
                }
                if (attempt < plan.retry.maxAttempts && shouldRetryStatus(plan.upperMethod, resp.statusCode, plan.retry.retryOn)) {
                    sleepBackoff(plan.retry, attempt, resp.headers != null ? resp.headers.get("retry-after") : null);
                    continue;
                }
                throw SdkHttpError.forStatus(resp.statusCode, resp.statusText, resp.body, resp.headers, resp.requestId, plan.errors);
            } catch (SdkHttpError e) {
                throw logError(cfg, plan.upperMethod, path, operationId, e);
            } catch (SdkTimeoutError e) {
                if (attempt < plan.retry.maxAttempts && mayRepeatRequest(plan)) {
                    sleepBackoff(plan.retry, attempt, null);
                    continue;
                }
                throw logError(cfg, plan.upperMethod, path, operationId, e);
            } catch (SdkNetworkError e) {
                if (attempt < plan.retry.maxAttempts && mayRepeatRequest(plan)) {
                    sleepBackoff(plan.retry, attempt, null);
                    continue;
                }
                throw logError(cfg, plan.upperMethod, path, operationId, e);
            }
        }

        // Reachable only if maxAttempts is misconfigured to 0.
        throw logError(plan.config, plan.upperMethod, path, operationId, new SdkNetworkError(new IllegalStateException(
            "Request '" + operationId + "' produced no attempts")));
    }

    private static final class RequestPlan {
        final SdkConfig.ClientConfig config;
        final SdkConfig.RetryConfig retry;
        final SdkConfig.IdempotencyConfig idempotency;
        final Duration timeout;
        final String upperMethod;
        final String url;
        final String resolvedContentType;
        final String bodyString;
        final byte[] bodyBytes;
        final String operationId;
        final boolean hasBody;
        final String idempotencyKey;
        final AuthResolved auth;
        final Map<String, String> extraHeaders;
        final Map<String, Class<? extends ErrorBody>> errors;

        RequestPlan(
            SdkConfig.ClientConfig config,
            SdkConfig.RetryConfig retry,
            SdkConfig.IdempotencyConfig idempotency,
            Duration timeout,
            String upperMethod,
            String url,
            String resolvedContentType,
            String bodyString,
            byte[] bodyBytes,
            String operationId,
            boolean hasBody,
            String idempotencyKey,
            AuthResolved auth,
            Map<String, String> extraHeaders,
            Map<String, Class<? extends ErrorBody>> errors
        ) {
            this.config = config;
            this.retry = retry;
            this.idempotency = idempotency;
            this.timeout = timeout;
            this.upperMethod = upperMethod;
            this.url = url;
            this.resolvedContentType = resolvedContentType;
            this.bodyString = bodyString;
            this.bodyBytes = bodyBytes;
            this.operationId = operationId;
            this.hasBody = hasBody;
            this.idempotencyKey = idempotencyKey;
            this.auth = auth;
            this.extraHeaders = extraHeaders;
            this.errors = errors;
        }

        SdkConfig.SdkRequest request(int attempt) {
            SdkConfig.SdkRequest req = new SdkConfig.SdkRequest();
            req.method = upperMethod;
            req.url = url;
            req.body = bodyString;
            req.bodyBytes = bodyBytes;
            req.contentType = resolvedContentType;
            req.operationId = operationId;
            req.attempt = attempt;
            if (config.auth != null) putHeaders(req.headers, config.auth.headers);
            putHeaders(req.headers, auth.headers);
            if (hasBody) {
                req.headers.put("Content-Type", resolvedContentType);
            }
            if (idempotencyKey != null) {
                req.headers.put(idempotency.headerName != null ? idempotency.headerName : "Idempotency-Key", idempotencyKey);
            }
            putHeaders(req.headers, extraHeaders);
            return req;
        }
    }

    private static RequestPlan prepareRequest(
        SdkConfig.ClientConfig config,
        String method,
        String path,
        Map<String, Object> query,
        Object body,
        String contentType,
        String operationId,
        Map<String, String> extraHeaders,
        SdkConfig.RequestOptions options,
        Map<String, Class<? extends ErrorBody>> errors
    ) {
        SdkConfig.ClientConfig cfg = config != null ? config : SdkConfig.getClientConfig();
        SdkConfig.RetryConfig retry = options != null && options.retry != null ? options.retry
            : cfg.retry != null ? cfg.retry : new SdkConfig.RetryConfig();
        SdkConfig.IdempotencyConfig idem = cfg.idempotency != null ? cfg.idempotency : new SdkConfig.IdempotencyConfig();
        Duration timeout = options != null && options.timeout != null ? options.timeout
            : cfg.timeout != null ? cfg.timeout : Duration.ofSeconds(30);
        String upperMethod = method.toUpperCase(Locale.ROOT);
        AuthResolved auth = resolveAuth(cfg, operationId);
        Map<String, Object> mergedQuery = auth.query.isEmpty() ? query : mergeQuery(query, auth.query);
        String url = buildUrl(requestBaseUrl(cfg, operationId), path, mergedQuery);
        String resolvedContentType = contentType != null ? contentType : "application/json";
        String bodyString = null;
        byte[] bodyBytes = null;
        Object wireBody = withStreamSelector(formFields(body, resolvedContentType), operationId, resolvedContentType);
        if (wireBody != null) {
            if (resolvedContentType.startsWith("multipart/form-data") && wireBody instanceof Map) {
                String boundary = "----InterfacerFormBoundary" + UUID.randomUUID().toString().replace("-", "");
                bodyBytes = encodeMultipart((Map<?, ?>) wireBody, boundary);
                resolvedContentType = "multipart/form-data; boundary=" + boundary;
            } else if (wireBody instanceof byte[] rawBytes) {
                bodyBytes = rawBytes;
            } else {
                bodyString = encodeBody(wireBody, resolvedContentType);
            }
        }
        String idempotencyKey = null;
        if (options != null && options.idempotencyKey != null) {
            idempotencyKey = options.idempotencyKey.isEmpty() ? null : options.idempotencyKey;
        } else if (idem.enabled && idem.methods != null && idem.methods.contains(upperMethod)) {
            idempotencyKey = UUID.randomUUID().toString();
        }
        return new RequestPlan(
            cfg,
            retry,
            idem,
            timeout,
            upperMethod,
            url,
            resolvedContentType,
            bodyString,
            bodyBytes,
            operationId,
            body != null,
            idempotencyKey,
            auth,
            withOptionHeaders(extraHeaders, options),
            errors
        );
    }

    private static Map<String, String> withOptionHeaders(Map<String, String> headers, SdkConfig.RequestOptions options) {
        if (options == null || options.headers == null || options.headers.isEmpty()) return headers;
        Map<String, String> merged = headers != null ? new HashMap<>(headers) : new HashMap<>();
        putHeaders(merged, options.headers);
        return merged;
    }

